// Package myriarch is the root package of the module. It carries the license
// texts that are compiled into the binaries: the project license (LICENSE) and
// the notices of the third-party software the binaries include
// (THIRD_PARTY_NOTICES, generated by scripts/gen-third-party-notices.sh).
// myriarchd serves both files under /licenses.
package myriarch

import _ "embed"

//go:embed LICENSE
var license string

//go:embed THIRD_PARTY_NOTICES
var thirdPartyNotices string

// License returns the text of the project license (Apache-2.0).
func License() string { return license }

// ThirdPartyNotices returns the notices and license texts of the third-party
// software included in the binaries.
func ThirdPartyNotices() string { return thirdPartyNotices }
